ENR[4] = {
 'Critique des hypothèses de la microéconomie standard': {
  'af': "Keen soutient que les hypothèses fondatrices de la théorie standard du consommateur ne sont pas des simplifications commodes mais des postulats démentis par l'observation, dont l'invalidité ruine les conclusions qu'on en tire. Sa thèse porte sur la structure déductive de la théorie : celle-ci procède d'axiomes sur les préférences — complétude, transitivité, non-satiété, convexité — dont elle déduit les courbes d'indifférence, puis la demande individuelle, puis la demande de marché. Chaque maillon dépend entièrement du précédent. Si la transitivité n'est pas vérifiée, on ne peut pas construire de fonction d'utilité ; sans fonction d'utilité, pas de courbe d'indifférence ; sans courbe d'indifférence, pas de demande individuelle bien définie. Keen insiste de surcroît sur une difficulté supplémentaire rarement enseignée : le passage des demandes individuelles à la demande de marché exige des conditions d'agrégation très restrictives, qui supposent en pratique des agents identiques ou une distribution des revenus sans effet.",
  'po': "Dans le chapitre, cette critique sert de contrepoint systématique à l'exposé du modèle du consommateur : elle oblige à distinguer ce que le modèle démontre et ce qu'il suppose. Elle introduit la question du statut des hypothèses en économie, qui permettra d'évaluer tout modèle rencontré ensuite dans le programme.",
  'co': "Steve Keen conteste la chaîne déductive de la microéconomie standard : si la transitivité des préférences n'est pas vérifiée, aucune fonction d'utilité ne peut être construite, et les conditions d'agrégation requises pour passer aux demandes de marché sont elles-mêmes très restrictives.",
 },
 'Critique de la non-satiété et de la croissance infinie': {
  'af': "Raworth soutient que l'hypothèse de non-satiété — préférer toujours davantage à moins — n'est ni descriptivement vraie ni théoriquement neutre, parce qu'elle inscrit la croissance illimitée au cœur même de l'analyse économique. Sa thèse est que des préférences supposées insatiables rendent impossible de qualifier un niveau de consommation de suffisant : aucun état ne peut être jugé satisfaisant, et toute politique devient par construction une politique de croissance. Elle propose de remplacer cet axiome par un espace borné de deux côtés : un plancher social, en deçà duquel les besoins fondamentaux ne sont pas couverts — alimentation, eau, santé, éducation, logement, participation politique — et un plafond écologique, au-delà duquel les limites planétaires sont franchies. L'objectif économique n'est plus de maximiser mais de se maintenir dans l'anneau situé entre les deux, ce qui redéfinit la réussite d'une économie.",
  'po': "Dans le chapitre, cette critique montre que les hypothèses du modèle du consommateur ne sont pas seulement techniques mais porteuses d'une norme implicite. Elle fournit l'articulation entre la microéconomie des préférences et les questions de soutenabilité traitées plus loin dans le programme.",
  'co': "Kate Raworth conteste l'axiome de non-satiété : en postulant des préférences insatiables, la théorie standard rend impossible de qualifier un niveau de consommation de suffisant et inscrit la croissance illimitée dans ses fondements mêmes.",
 },
 "Loi de décroissance de l'utilité marginale": {
  'af': "Gossen établit que chaque unité supplémentaire d'un même bien consommée dans un temps donné procure une satisfaction additionnelle inférieure à celle de la précédente. La thèse paraît modeste et commande en réalité la quasi-totalité de la théorie du consommateur. Son fondement est que le besoin auquel le bien répond se sature progressivement : les premières unités satisfont les usages les plus urgents, les suivantes des usages de moins en moins pressants. Trois conséquences majeures en découlent. La courbe de demande est décroissante, puisqu'il faut un prix plus bas pour qu'un consommateur accepte une unité de moindre utilité. Le consommateur diversifie sa consommation au lieu de concentrer sa dépense sur un seul bien, puisqu'il égalise les utilités marginales pondérées par les prix. Enfin, les courbes d'indifférence sont convexes, ce qui garantit l'existence d'un optimum unique et rend le modèle mathématiquement opérant.",
  'po': "Dans le chapitre, cette loi constitue le socle technique de toute l'analyse du consommateur : la décroissance de l'utilité marginale, la convexité des courbes d'indifférence et la décroissance du taux marginal de substitution sont trois expressions de la même propriété. Elle fournit également, par contraste, l'argument de satiété que Raworth oppose à la non-satiété.",
  'co': "La première loi de Gossen établit que l'utilité marginale décroît avec la quantité consommée : cette propriété fonde la décroissance de la courbe de demande, la convexité des courbes d'indifférence et la diversification des achats du consommateur.",
 },
 'Rationalité limitée et comportement satisfaisant': {
  'af': "Simon soutient que les agents économiques ne maximisent pas et ne peuvent pas maximiser : ils recherchent une solution satisfaisante. Sa thèse n'est pas que les individus sont irrationnels, mais que la rationalité doit être redéfinie. Maximiser suppose en effet de connaître l'ensemble des options possibles, d'en évaluer toutes les conséquences et de les ordonner complètement, exigences hors de portée dans un environnement complexe où l'information est coûteuse, le temps limité et les capacités cognitives bornées. Simon oppose donc à la rationalité substantielle, qui juge une décision par son résultat optimal, une rationalité procédurale, qui juge une décision par la qualité de la procédure suivie pour l'atteindre. L'agent se fixe un niveau d'aspiration, explore les options séquentiellement et s'arrête à la première qui l'atteint : il satisfait au lieu de maximiser.",
  'po': "Dans le chapitre, cette thèse fournit l'alternative constructive aux critiques de l'homo œconomicus : elle ne se contente pas de récuser la maximisation, elle propose un autre modèle de décision. Elle explique des comportements que la théorie standard ne prédit pas — rôle des routines, inertie, dépendance du résultat à l'ordre d'exploration — et sera réemployée pour analyser la firme et les organisations.",
  'co': "Herbert Simon substitue à la rationalité substantielle une rationalité procédurale : l'information et les capacités cognitives étant limitées, l'agent ne maximise pas mais se fixe un niveau d'aspiration et retient la première option qui l'atteint.",
 },
 'Système 1, Système 2 et biais cognitifs': {
  'af': "Kahneman soutient que le raisonnement humain combine deux modes de fonctionnement distincts, et que la prédominance du premier engendre des erreurs systématiques et prévisibles. Le Système 1 est rapide, automatique, intuitif et sans effort ; le Système 2 est lent, délibéré, coûteux en attention. Sa thèse est que, l'attention étant une ressource rare, l'esprit délègue par défaut au Système 1, lequel procède par heuristiques : juger de la fréquence d'un événement par la facilité avec laquelle un exemple vient à l'esprit, estimer une valeur en partant d'un nombre présent dans l'énoncé, évaluer un gain relativement à un point de référence plutôt qu'en niveau. Le point décisif, et ce qui distingue cette analyse d'un simple constat d'imperfection, est que les erreurs produites sont systématiques et non aléatoires : elles vont toujours dans le même sens, ne se compensent donc pas entre individus et subsistent à l'agrégation.",
  'po': "Dans le chapitre, cette analyse apporte la validation expérimentale des critiques adressées à l'hypothèse de rationalité : il ne s'agit plus d'une objection de principe mais de résultats reproductibles. Elle conduit à réexaminer la stabilité des préférences, hypothèse pourtant nécessaire à la construction des courbes d'indifférence.",
  'co': "Kahneman distingue un Système 1 rapide et intuitif d'un Système 2 lent et délibéré : la prédominance du premier engendre des biais systématiques — ancrage, disponibilité, cadrage, aversion aux pertes — qui, étant orientés, ne se compensent pas à l'agrégation.",
 },
 'Nudge et architecture des choix': {
  'af': "Thaler soutient que, puisque les préférences exprimées dépendent de la façon dont les options sont présentées, il est possible d'améliorer les décisions sans contrainte ni interdiction, en modifiant la seule architecture du choix. La thèse repose sur un renversement : ce que la théorie standard traite comme une anomalie — la dépendance du choix au cadrage — devient un levier d'action. Le biais de statu quo fait que l'option par défaut est très majoritairement retenue ; il suffit donc de changer le défaut pour changer le comportement dominant, tout en laissant chacun libre d'en sortir. Thaler nomme paternalisme libertarien cette position : paternaliste parce qu'elle oriente vers un comportement jugé préférable, libertarienne parce qu'elle ne ferme aucune option. L'intérêt pour l'analyse économique est qu'elle fournit un instrument de politique publique distinct de la taxe, de la subvention et de la norme.",
  'po': "Dans le chapitre, cette idée tire les conséquences pratiques de l'instabilité des préférences établie par Kahneman : si les préférences ne sont pas données mais construites par le contexte, le contexte devient un objet de politique publique. Elle fournit un troisième terme entre marché et réglementation.",
  'co': "Richard Thaler montre que l'architecture des choix modifie les comportements sans contraindre : parce que l'option par défaut est très majoritairement retenue, en changer suffit à déplacer le comportement dominant tout en préservant la liberté de choix.",
 },
 'Prophétie autoréalisatrice': {
  'af': "Merton soutient qu'une croyance initialement fausse peut devenir vraie par ses seuls effets, en modifiant les comportements de manière à produire la situation qu'elle annonçait. La thèse a une portée particulière en économie parce qu'elle n'exige aucune irrationalité des agents. La séquence comporte trois temps : une définition de la situation se diffuse, même sans fondement ; chaque agent, pris individuellement, agit rationnellement compte tenu de cette croyance et de ce qu'il anticipe du comportement des autres ; la somme de ces actions rationnelles valide la croyance. Merton établit par là que les représentations collectives ne sont pas un commentaire extérieur sur la réalité économique mais une composante de cette réalité. Le mécanisme fonctionne symétriquement, à la hausse comme à la baisse, et il explique que des situations parfaitement saines puissent se dégrader sans qu'aucun fondamental n'ait changé.",
  'po': "Dans le chapitre, cette idée montre que l'écart à la rationalité standard n'est pas toujours individuel : il peut naître de l'interaction entre des agents parfaitement rationnels. Elle introduit le rôle des anticipations et des croyances, indispensable pour comprendre les marchés financiers et les crises de confiance.",
  'co': "La prophétie autoréalisatrice décrite par Merton montre qu'une croyance peut produire la réalité qu'elle annonce : chaque agent agissant rationnellement compte tenu de ce qu'il anticipe des autres, la somme de ces comportements valide la croyance initiale, fût-elle infondée.",
 },
}

ENR[5] = {
 'Externalités et taxation correctrice': {
  'af': "Pigou soutient que lorsque l'activité d'un agent affecte le bien-être d'autrui sans qu'aucune transaction ne vienne en tenir compte, le coût supporté par le producteur diverge du coût supporté par la collectivité, et le marché, même parfaitement concurrentiel, conduit à une allocation inefficace. Sa thèse établit donc un résultat important : l'inefficacité ne provient pas ici d'un défaut de concurrence mais de l'absence d'un marché. Le producteur égalise son coût marginal privé au prix sans tenir compte du dommage infligé aux tiers ; comme le coût social excède le coût privé, la quantité produite excède la quantité socialement souhaitable. Pigou en déduit la solution qui portera son nom : instaurer une taxe égale au dommage marginal évalué à l'optimum, de façon à internaliser l'écart. Le producteur, confronté à un coût privé désormais égal au coût social, réduit spontanément sa production au bon niveau, sans qu'il soit nécessaire d'interdire l'activité.",
  'po': "Dans le chapitre, cette analyse fonde la légitimité économique de l'intervention publique : elle montre qu'un marché concurrentiel peut être inefficace, ce qui ne pouvait pas se déduire du modèle walrasien. Elle fournit le premier type de défaillance étudié et l'instrument de référence auquel seront comparées les autres solutions.",
  'co': "Pigou établit que l'existence d'externalités fait diverger coût privé et coût social : le marché produit alors une quantité excessive, et une taxe égale au dommage marginal permet d'internaliser l'écart sans interdire l'activité.",
 },
 'Théorème de Coase et coûts de transaction': {
  'af': "Coase soutient qu'une externalité est un problème de droits mal définis plutôt qu'un problème de prix manquant, et que si les droits de propriété sont clairement attribués et les coûts de transaction négligeables, les parties concernées négocieront d'elles-mêmes une solution efficace, quelle que soit la partie à laquelle le droit a été initialement attribué. Le résultat est doublement contre-intuitif : l'efficacité ne dépend pas de l'identité du titulaire du droit, et aucune intervention publique n'est requise pour l'atteindre. Mais la thèse de Coase est souvent tronquée, car l'essentiel de son argumentation porte sur la réciproque : dès lors que les coûts de transaction — identifier les parties concernées, négocier, rédiger un accord, en faire respecter les termes — deviennent élevés, la négociation échoue et une intervention devient nécessaire. Le théorème sert donc moins à écarter l'État qu'à identifier les situations où il est indispensable.",
  'po': "Dans le chapitre, cette thèse introduit une alternative à la solution pigouvienne et surtout la notion de coût de transaction, dont la portée dépassera de loin l'analyse des externalités puisqu'elle fondera la théorie de la firme. Elle montre que le choix entre marché, négociation privée et intervention publique dépend d'une comparaison de coûts et non d'une position de principe.",
  'co': "Le théorème de Coase établit que, si les droits de propriété sont définis et les coûts de transaction faibles, la négociation privée conduit à une solution efficace quelle que soit l'attribution initiale du droit : la réciproque, qui en est l'essentiel, est que des coûts de transaction élevés rendent l'intervention publique nécessaire.",
 },
 'Sélection adverse et marché des lemons': {
  'af': "Akerlof soutient qu'une asymétrie d'information portant sur la qualité, antérieure à la transaction, peut éliminer les biens de bonne qualité d'un marché et, à la limite, détruire le marché lui-même. La thèse est remarquable parce qu'elle décrit une défaillance qui s'aggrave d'elle-même. L'acheteur, incapable de distinguer la bonne qualité de la mauvaise, n'accepte de payer que le prix correspondant à la qualité moyenne qu'il anticipe. À ce prix, les vendeurs détenant des biens de qualité supérieure à la moyenne se retirent, puisqu'ils y perdraient. La qualité moyenne des biens restants baisse donc effectivement, l'acheteur révise son prix à la baisse, et une nouvelle strate de bons vendeurs se retire à son tour. Le processus est cumulatif : à la limite, seuls subsistent les plus mauvais produits, que l'anglais nomme lemons, ou bien plus aucune transaction n'a lieu.",
  'po': "Dans le chapitre, cette analyse introduit la troisième grande famille de défaillances — l'information imparfaite — après les externalités et le pouvoir de marché. Elle montre que le prix, qui dans le modèle walrasien transmet toute l'information nécessaire, peut au contraire détruire l'information lorsqu'il est le seul signal disponible.",
  'co': "Akerlof montre qu'une asymétrie d'information sur la qualité engendre une sélection adverse : l'acheteur n'offrant que le prix de la qualité moyenne, les meilleurs vendeurs se retirent, ce qui dégrade la qualité moyenne et peut conduire à la disparition du marché.",
 },
 'Signalement : le diplôme comme signal': {
  'af': "Spence soutient que, lorsqu'une qualité est inobservable, l'agent qui la détient peut la révéler en adoptant un comportement coûteux que les autres n'auraient pas intérêt à imiter. La thèse repose sur une condition précise, sans laquelle le signal ne fonctionne pas : il doit être moins coûteux à produire pour les agents de bonne qualité. Le diplôme remplit cette condition, puisqu'obtenir un titre exigeant demande moins d'effort à un individu productif. Il devient alors rationnel pour celui-ci de s'y engager et pour l'individu peu productif de s'en abstenir, de sorte que l'employeur peut inférer la qualité de la seule observation du diplôme. Le résultat le plus frappant de l'analyse, et celui qui la distingue de la théorie du capital humain, est que le signal demeure informatif même si la formation n'a rien appris : ce qui informe n'est pas le contenu acquis mais le coût différencié de l'acquisition.",
  'po': "Dans le chapitre, cette thèse apporte la réponse au problème posé par Akerlof : le marché peut engendrer lui-même des dispositifs de révélation de l'information, ce qui nuance la nécessité d'une intervention publique. Elle ouvre aussi une question centrale sur l'éducation, puisqu'elle dissocie la valeur du diplôme de son contenu formatif.",
  'co': "Michael Spence montre qu'un signal coûteux révèle une qualité inobservable à condition d'être moins coûteux pour les agents de bonne qualité : le diplôme informe alors l'employeur même si la formation n'a accru aucune productivité.",
 },
 'Gouvernance collective des communs': {
  'af': "Ostrom soutient qu'entre la privatisation et l'étatisation existe une troisième voie, que l'analyse économique avait négligée : des communautés d'usagers peuvent gérer durablement une ressource commune en se dotant elles-mêmes de règles, et le font effectivement depuis des siècles. Sa thèse n'est pas une position normative mais le résultat d'enquêtes de terrain comparées, dont elle tire les principes récurrents des dispositifs qui durent : des frontières clairement définies de la ressource et du groupe d'ayants droit ; des règles d'usage adaptées aux conditions locales ; la participation des usagers à leur élaboration ; une surveillance assurée par les usagers eux-mêmes ; des sanctions graduées plutôt qu'une exclusion immédiate ; des mécanismes de résolution des conflits peu coûteux ; et la reconnaissance par l'autorité extérieure du droit de la communauté à s'organiser. Le ressort commun est l'observabilité réciproque, qui rend le coût du contrôle supportable.",
  'po': "Dans le chapitre, cette analyse constitue le dépassement de l'alternative marché-État qui structure l'étude des défaillances : elle montre que le choix n'est pas binaire et que l'efficacité dépend de l'agencement institutionnel plutôt que du régime de propriété. Elle réfute empiriquement le caractère inéluctable de la tragédie des communs.",
  'co': "Elinor Ostrom établit, à partir d'enquêtes comparées, que des communautés d'usagers gèrent durablement des ressources communes grâce à des règles élaborées localement, une surveillance mutuelle et des sanctions graduées : ni la privatisation ni l'étatisation ne sont les seules issues.",
 },
 'Tragédie des communs': {
  'af': "Hardin soutient qu'une ressource commune en libre accès est vouée à la surexploitation, et que ce résultat découle de comportements parfaitement rationnels plutôt que d'une ignorance ou d'une malveillance. La thèse repose sur une dissymétrie entre les bénéfices et les coûts d'une décision individuelle : l'usager qui prélève une unité supplémentaire en capte la totalité du bénéfice, tandis que le coût de l'épuisement est réparti sur l'ensemble des usagers. Son calcul privé lui est donc systématiquement favorable, alors même qu'il sait la ressource menacée, puisque s'abstenir ne ferait que laisser sa part aux autres. Hardin met ainsi en évidence une divergence structurelle entre rationalité individuelle et rationalité collective. L'important est que cette divergence ne tient ni aux préférences des agents ni à leur information, mais à la structure des droits : c'est l'absence d'exclusion qui produit le résultat.",
  'po': "Dans le chapitre, cette analyse constitue le cas d'école de défaillance liée aux biens communs, c'est-à-dire aux biens rivaux mais non excluables, et complète la typologie des biens étudiée ici. Elle justifie l'examen des trois réponses possibles — privatisation, réglementation publique, gouvernance collective — qui structure la suite du raisonnement.",
  'co': "La tragédie des communs décrite par Hardin résulte d'une dissymétrie : l'usager capte la totalité du bénéfice d'un prélèvement supplémentaire alors que le coût de l'épuisement est partagé, de sorte que des comportements individuellement rationnels détruisent collectivement la ressource.",
 },
 "Logique de l'action collective et passager clandestin": {
  'af': "Olson soutient qu'un groupe partageant un intérêt commun n'agit pas spontanément pour le défendre, parce qu'il est individuellement rationnel de bénéficier du résultat sans supporter le coût de l'action. La thèse renverse une intuition sociologique courante selon laquelle les intérêts communs engendrent naturellement des mobilisations. Le raisonnement est le suivant : un bien collectif étant par définition non excluable, il profite à tous les membres du groupe, contributeurs ou non ; or la contribution d'un individu a un coût certain et un effet négligeable sur l'obtention du bien ; s'abstenir est donc la stratégie dominante. Olson en tire un résultat contre-intuitif et empiriquement vérifié : les petits groupes s'organisent plus facilement que les grands, car la contribution individuelle y est déterminante et l'abstention repérable. Les grands groupes ne s'organisent que par des incitations sélectives, c'est-à-dire des avantages réservés aux seuls membres.",
  'po': "Dans le chapitre, cette analyse généralise le mécanisme de Hardin à l'ensemble des biens collectifs et explique pourquoi la production de ces biens ne peut pas être laissée au volontariat. Elle fournit en outre un outil d'économie politique qui servira à comprendre pourquoi les politiques publiques favorisent souvent des intérêts concentrés contre des intérêts diffus.",
  'co': "Mancur Olson montre qu'un groupe aux intérêts communs ne se mobilise pas spontanément : le bien collectif étant non excluable, l'abstention est individuellement rationnelle, et seuls les petits groupes ou ceux disposant d'incitations sélectives surmontent le problème du passager clandestin.",
 },
 "Public Choice : la défaillance de l'État": {
  'af': "Buchanan soutient que les décideurs publics ne poursuivent pas un intérêt général désincarné mais, comme les agents privés, leur propre utilité, et qu'il faut par conséquent comparer la défaillance du marché à la défaillance de l'État plutôt qu'à un État idéal. La thèse applique l'analyse économique à la sphère politique elle-même, ce qui constitue son apport méthodologique. L'élu cherche sa réélection, ce qui l'oriente vers les dépenses visibles et les coûts différés ; le fonctionnaire cherche l'extension de son budget et de ses compétences ; le groupe d'intérêt concentré obtient des avantages aux dépens d'une majorité dispersée. La décision publique est donc structurellement biaisée vers la dépense, le court terme et la capture, non par malhonnêteté mais par la structure des incitations. Buchanan en déduit que le remède ne réside pas dans le choix de meilleurs dirigeants mais dans des règles constitutionnelles contraignant les choix à l'avance.",
  'po': "Dans le chapitre, cette critique est indispensable à l'équilibre du raisonnement : après avoir établi que le marché peut être défaillant, elle interdit d'en conclure automatiquement que l'État doit intervenir. Elle impose la comparaison entre deux imperfections, qui est la forme correcte de la question.",
  'co': "James Buchanan et le courant du Public Choice montrent que les décideurs publics poursuivent aussi leurs intérêts propres : la comparaison pertinente n'oppose pas un marché réel à un État idéal mais deux imperfections, ce qui justifie des règles contraignant la décision publique à l'avance.",
 },
 'Capture réglementaire': {
  'af': "Stigler soutient que la réglementation, conçue pour protéger le public, finit fréquemment par servir les intérêts du secteur qu'elle est censée encadrer. La thèse décrit un mécanisme, non une corruption : elle n'implique aucune faute individuelle. Le régulateur dépend des régulés pour son information technique, ce qui crée une asymétrie en leur faveur ; les régulés sont peu nombreux, fortement intéressés et durablement organisés, tandis que les bénéficiaires de la réglementation sont dispersés et faiblement intéressés pris individuellement, de sorte que la pression exercée est asymétrique ; les carrières, enfin, circulent entre l'administration et le secteur. La réglementation dérive alors vers la protection des positions établies — barrières à l'entrée, normes taillées pour les acteurs en place, tarifs garantis — tout en conservant la forme et le vocabulaire d'une protection du public.",
  'po': "Dans le chapitre, cette analyse précise le contenu de la défaillance de l'État énoncée par Buchanan et en fournit le cas le plus documenté. Elle montre que l'instrument réglementaire, souvent présenté comme la réponse évidente à une défaillance de marché, comporte son propre risque d'inefficacité.",
  'co': "George Stigler met en évidence la capture réglementaire : dépendant des régulés pour son information et soumis à une pression asymétrique, le régulateur protège progressivement les positions établies sous couvert de protéger le public.",
 },
 'Tragédie des anti-communs': {
  'af': "Heller soutient que l'excès de droits de propriété est aussi destructeur que leur absence : lorsque trop d'acteurs détiennent un droit de veto sur l'usage d'une ressource, celle-ci reste inexploitée. La thèse constitue la symétrie exacte de celle de Hardin. Là où Hardin décrit un bien sans propriétaire, donc surexploité, Heller décrit un bien à propriétaires multiples, donc sous-exploité. Si l'usage d'une ressource exige l'accord de nombreux titulaires, chacun peut bloquer et chacun a intérêt à surévaluer sa part ; la négociation échoue, non faute de droits, mais par leur fragmentation. Le résultat est important pour l'analyse économique parce qu'il retourne l'argument de Coase contre la privatisation systématique : définir davantage de droits ne réduit pas toujours les coûts de transaction, cela peut au contraire les rendre prohibitifs. La bonne question n'est donc pas « plus ou moins de propriété » mais « quelle structure de droits ».",
  'po': "Dans le chapitre, cette analyse clôt l'examen des régimes de propriété en montrant que ni le libre accès ni la propriété privée fragmentée ne garantissent l'efficacité. Elle conforte la conclusion institutionnaliste d'Ostrom : ce qui compte est l'agencement des règles, et non le régime de propriété pris abstraitement.",
  'co': "Michael Heller met en évidence une tragédie des anti-communs : lorsque trop d'acteurs détiennent un droit de veto, la ressource reste inexploitée, ce qui montre que la multiplication des droits de propriété peut élever les coûts de transaction au lieu de les réduire.",
 },
}
